import React, { useState, useEffect, useCallback } from 'react';
import axios from 'axios';
import CourseCard from '../components/CourseCard';

const categories = ['All', 'Programming', 'Design', 'Business', 'Marketing', 'Photography', 'Music', 'Data Science', 'AI & ML'];
const levels = ['All', 'beginner', 'intermediate', 'advanced'];

export default function CoursesPage() {
  const [courses, setCourses] = useState([]);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState('');
  const [category, setCategory] = useState('All');
  const [level, setLevel] = useState('All');
  const [page, setPage] = useState(1);
  const [totalPages, setTotalPages] = useState(1);
  const [total, setTotal] = useState(0);

  const fetchCourses = useCallback(async () => {
    setLoading(true);
    try {
      const params = new URLSearchParams({ page, limit: 9 });
      if (search) params.set('search', search);
      if (category !== 'All') params.set('category', category);
      if (level !== 'All') params.set('level', level);
      const { data } = await axios.get(`/api/courses?${params}`);
      setCourses(data.courses || []);
      setTotalPages(data.pages || 1);
      setTotal(data.total || 0);
    } catch { setCourses([]); }
    setLoading(false);
  }, [search, category, level, page]);

  useEffect(() => { setPage(1); }, [search, category, level]);
  useEffect(() => { fetchCourses(); }, [fetchCourses]);

  return (
    <div style={{ minHeight: '100vh', paddingTop: 90 }}>
      {/* Header */}
      <div style={{ background: 'linear-gradient(180deg, rgba(124,58,237,0.12) 0%, transparent 100%)', padding: '48px 0 36px', borderBottom: '1px solid rgba(124,58,237,0.1)' }}>
        <div className="page-container">
          <h1 style={{ fontSize: 'clamp(28px, 4vw, 44px)', fontWeight: 900, marginBottom: 8, animation: 'fadeUp 0.5s ease' }}>
            Explore <span style={{ background: 'linear-gradient(135deg, #7c3aed, #00f5d4)', WebkitBackgroundClip: 'text', WebkitTextFillColor: 'transparent' }}>All Courses</span>
          </h1>
          <p style={{ color: '#6b6490', marginBottom: 28 }}>{total} courses available</p>

          {/* Search */}
          <div style={{ position: 'relative', maxWidth: 520, marginBottom: 28 }}>
            <span style={{ position: 'absolute', left: 16, top: '50%', transform: 'translateY(-50%)', fontSize: 18, pointerEvents: 'none' }}>🔍</span>
            <input className="input" placeholder="Search courses, topics, instructors..."
              value={search} onChange={e => setSearch(e.target.value)}
              style={{ paddingLeft: 46, fontSize: 15, height: 50 }} />
          </div>

          {/* Filters */}
          <div style={{ display: 'flex', gap: 12, flexWrap: 'wrap' }}>
            <div style={{ display: 'flex', gap: 6, flexWrap: 'wrap' }}>
              {categories.map(c => (
                <button key={c} onClick={() => setCategory(c)} style={{
                  padding: '7px 16px', borderRadius: 100, border: 'none', cursor: 'pointer',
                  fontSize: 13, fontWeight: 600, transition: 'all 0.2s',
                  background: category === c ? 'linear-gradient(135deg, #7c3aed, #a855f7)' : 'rgba(124,58,237,0.1)',
                  color: category === c ? 'white' : '#b8b0d8',
                  boxShadow: category === c ? '0 4px 20px rgba(124,58,237,0.4)' : 'none'
                }}>{c}</button>
              ))}
            </div>
          </div>

          <div style={{ display: 'flex', gap: 8, marginTop: 12, flexWrap: 'wrap' }}>
            <span style={{ fontSize: 13, color: '#6b6490', alignSelf: 'center', marginRight: 4 }}>Level:</span>
            {levels.map(l => (
              <button key={l} onClick={() => setLevel(l)} style={{
                padding: '5px 14px', borderRadius: 100, border: `1px solid ${level === l ? '#7c3aed' : 'rgba(124,58,237,0.2)'}`,
                cursor: 'pointer', fontSize: 12, fontWeight: 600, transition: 'all 0.2s',
                background: level === l ? 'rgba(124,58,237,0.2)' : 'transparent',
                color: level === l ? '#c084fc' : '#6b6490', textTransform: 'capitalize'
              }}>{l}</button>
            ))}
          </div>
        </div>
      </div>

      {/* Courses Grid */}
      <div className="page-container" style={{ padding: '48px 24px' }}>
        {loading ? (
          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(300px, 1fr))', gap: 24 }}>
            {[...Array(6)].map((_, i) => (
              <div key={i} style={{ height: 360, borderRadius: 16, background: 'rgba(124,58,237,0.06)', animation: 'pulse-glow 1.5s ease-in-out infinite' }} />
            ))}
          </div>
        ) : courses.length === 0 ? (
          <div style={{ textAlign: 'center', padding: '80px 0' }}>
            <div style={{ fontSize: 64, marginBottom: 16 }}>🔍</div>
            <h3 style={{ fontSize: 22, fontWeight: 700, marginBottom: 8, color: '#f0eeff' }}>No courses found</h3>
            <p style={{ color: '#6b6490' }}>Try adjusting your search or filters</p>
          </div>
        ) : (
          <>
            <div className="grid-courses">
              {courses.map((c, i) => <CourseCard key={c._id} course={c} delay={i * 0.06} />)}
            </div>

            {/* Pagination */}
            {totalPages > 1 && (
              <div style={{ display: 'flex', justifyContent: 'center', gap: 8, marginTop: 48 }}>
                <button className="btn btn-ghost btn-sm" onClick={() => setPage(p => Math.max(1, p - 1))} disabled={page === 1}>← Prev</button>
                {[...Array(totalPages)].map((_, i) => (
                  <button key={i} onClick={() => setPage(i + 1)} style={{
                    width: 36, height: 36, borderRadius: 8, border: 'none', cursor: 'pointer',
                    fontWeight: 700, fontSize: 14, transition: 'all 0.2s',
                    background: page === i + 1 ? 'linear-gradient(135deg, #7c3aed, #a855f7)' : 'rgba(124,58,237,0.1)',
                    color: page === i + 1 ? 'white' : '#b8b0d8'
                  }}>{i + 1}</button>
                ))}
                <button className="btn btn-ghost btn-sm" onClick={() => setPage(p => Math.min(totalPages, p + 1))} disabled={page === totalPages}>Next →</button>
              </div>
            )}
          </>
        )}
      </div>
    </div>
  );
}
